function chem11AddSection(chapterId, section) {
  const chapter = CHEM_11_DATA.find(item => item.id === chapterId);
  if (!chapter) throw new Error(`Unknown Chemistry chapter ${chapterId}`);
  const current = chapter.sections.find(item => item.source.pdfPage === section.source.pdfPage);
  if (current) Object.assign(current, section);
  else chapter.sections.push(section);
  return section;
}

function chemistry11StoichiometryOutcomeSvg() {
  const atom=(x,y,r,colour)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${colour}" stroke="#475569" stroke-width="1.4"/>`;
  const h=(x,y)=>atom(x,y,10,'#f1f5f9'),o=(x,y)=>atom(x,y,15,'#b91c4b'),c=(x,y)=>atom(x,y,18,'#303b48');
  const water=(x,y)=>`<path d="M${x-18} ${y+17}L${x} ${y}L${x+18} ${y+17}" stroke="#475569" fill="none" stroke-width="2"/>${o(x,y)}${h(x-18,y+17)}${h(x+18,y+17)}`;
  return `<svg viewBox="0 0 550 165" role="img" aria-labelledby="chem11-stoich-title chem11-stoich-desc" style="width:min(100%,600px);height:auto"><title id="chem11-stoich-title">CH₄ + 2O₂ → CO₂ + 2H₂O</title><desc id="chem11-stoich-desc">One methane molecule with one carbon and four hydrogens, two oxygen molecules with two oxygens each, one carbon dioxide molecule with one carbon and two oxygens, and two water molecules with one oxygen and two hydrogens each.</desc><g stroke="#475569" stroke-width="2"><path d="M70 70L50 40M70 70L96 58M70 70L75 96M70 70L44 86M182 45H207M182 92H207M332 70H378M255 70H298"/></g><path d="M305 70L290 62V78Z" fill="#475569"/>${c(70,70)}${h(50,40)}${h(96,58)}${h(75,96)}${h(44,86)}${o(182,45)}${o(207,45)}${o(182,92)}${o(207,92)}${c(355,70)}${o(332,70)}${o(378,70)}${water(470,39)}${water(470,92)}<g font-family="sans-serif" font-size="22" fill="#1f2937" text-anchor="middle"><text x="131" y="79">+</text><text x="417" y="79">+</text><text x="70" y="148">CH₄</text><text x="131" y="148">+</text><text x="195" y="148">2O₂</text><text x="279" y="148">→</text><text x="355" y="148">CO₂</text><text x="417" y="148">+</text><text x="470" y="148">2H₂O</text></g></svg>`;
}

