function chemistry11AvogadroSvg() {
  return `<svg viewBox="0 0 480 290" role="img" aria-labelledby="chem11-avogadro-title chem11-avogadro-desc" style="width:min(100%,480px);height:auto"><title id="chem11-avogadro-title">Mole and Avogadro’s number, N subscript A</title><desc id="chem11-avogadro-desc">A single-pan dial weighing scale carries a carbon-12 sample. Twelve grams of carbon-12 equals one mole, or 6.023 times ten to the twenty-third particles.</desc><path d="M305 62Q350 7 405 62Z" fill="#322b27" stroke="#262626" stroke-width="2"/><path d="M270 63H440L425 84H285Z" fill="#42647b" stroke="#243746" stroke-width="3"/><rect x="320" y="84" width="68" height="15" fill="#332b27"/><rect x="312" y="99" width="85" height="135" rx="4" fill="#b56f55" stroke="#663d31" stroke-width="3"/><circle cx="355" cy="160" r="34" fill="#e9e5d4" stroke="#8d8772" stroke-width="2"/><path d="M355 160L368 143" stroke="#3f473f" stroke-width="4"/><circle cx="355" cy="160" r="3" fill="#665349"/><g font-family="sans-serif" fill="#172f3d"><text x="20" y="106" font-size="28" font-weight="700">1 mole =</text><text x="20" y="151" font-size="33" font-weight="700">6.023 × 10<tspan dy="-17" font-size="21">23</tspan></text><text x="20" y="187" font-size="21" font-weight="700" fill="#a82b4c">Avogadro’s Number</text><text x="355" y="267" text-anchor="middle" font-size="16">12 grams of carbon-12=1 mole</text></g></svg>`;
}

