const chem11MathVocabulary={
  'number of moles(n)':['مولوں کی تعداد (n)','د مولونو شمېر (n)'],
  'mass(g)':['کمیت (g)','کتله (g)'],
  'molar mass of naoh(g/mol))':['NaOH کی مولر کمیت (g/mol))','د NaOH مولر کتله (g/mol))'],
  'molar mass of caco₃(g/mol)':['CaCO₃ کی مولر کمیت (g/mol)','د CaCO₃ مولر کتله (g/mol)'],
  'number of h₂o molecules':['H₂O سالمات کی تعداد','د H₂O ماليکولونو شمېر'],
  'avogadro’s number':['ایووگاڈرو کا عدد','د اېووګادرو شمېره'],
  'or Mass = 0.5 × 100 = 50 g':['یا کمیت = 0.5 × 100 = 50 g','يا کتله = 0.5 × 100 = 50 g']
};
function chem11WorkedFraction(id,parts,latex,exampleId) {
  const translated=language=>Object.fromEntries(Object.entries(parts).map(([key,value])=>[key,(chem11MathVocabulary[value.toLowerCase()]||chem11MathVocabulary[value]||[value,value])[language]]));
  return {id,parts,latex,exampleId,accessible:`${parts.left} equals ${parts.numerator} divided by ${parts.denominator}${parts.result?` equals ${parts.result}`:''}${parts.after?` ${parts.after}`:''}`,translations:{ur:translated(0),ps:translated(1)}};
}
