function chemistry11ConversionSvg() {
  const node=(x,y,label,fill,small='')=>`<circle cx="${x}" cy="${y}" r="52" fill="${fill}" stroke="#64705c" stroke-width="2"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="23" font-weight="700">${label}</text>${small?`<text x="${x}" y="${y+29}" text-anchor="middle" font-size="16">${small}</text>`:''}`;
  const link=(x1,y1,x2,y2)=>{const a=Math.atan2(y2-y1,x2-x1)*180/Math.PI;return `<path d="M${x1} ${y1}L${x2} ${y2}" stroke="#354330" stroke-width="2"/><path d="M0 0L-9 -4L-9 4Z" fill="#354330" transform="translate(${x2} ${y2}) rotate(${a})"/><path d="M0 0L-9 -4L-9 4Z" fill="#354330" transform="translate(${x1} ${y1}) rotate(${a+180})"/>`;};
  const ratio=(x,y,angle,den,extra='')=>`<g transform="translate(${x} ${y}) rotate(${angle})"><text x="0" y="-9" text-anchor="middle" font-size="18">1 mole =</text><path d="M-110 0H110" stroke="#354330"/><text x="0" y="23" text-anchor="middle" font-size="18">${den}</text>${extra?`<text x="0" y="44" text-anchor="middle" font-size="16">particles</text><text x="0" y="64" text-anchor="middle" font-size="16">(atoms or molecules)</text>`:''}</g>`;
  return `<svg viewBox="0 0 1000 640" role="img" aria-labelledby="chem11-conv-title chem11-conv-desc" style="width:min(100%,1000px);height:auto"><rect width="1000" height="640" fill="white"/><title id="chem11-conv-title">Representation of different Conversions</title><desc id="chem11-conv-desc">Mass, volume of gases and particles convert in both directions to moles for substances A and B. Balanced chemical equation coefficients relate the moles of the two substances.</desc><text x="300" y="35" text-anchor="middle" font-size="23" font-weight="700">Substance A</text><text x="700" y="35" text-anchor="middle" font-size="23" font-weight="700">Substance B</text><path d="M500 45V605" stroke="#596653" stroke-dasharray="3 5" stroke-width="2"/><rect x="409" y="165" width="182" height="80" fill="white"/><text x="500" y="185" text-anchor="middle" font-size="17"><tspan x="500">Use coefficients</tspan><tspan x="500" dy="23">from balanced</tspan><tspan x="500" dy="23">chemical equation</tspan></text>${node(90,115,'Mass','#e1e8bc')}${node(90,325,'Volume','#e1e8bc','(gases)')}${node(90,540,'Particles','#e1e8bc')}${node(385,325,'Mole','#e1e8bc')}${node(615,325,'Mole','#c9abd5')}${node(910,115,'Mass','#c9abd5')}${node(910,325,'Volume','#c9abd5','(gases)')}${node(910,540,'Particles','#c9abd5')}${link(129,151,346,289)}${link(142,325,333,325)}${link(129,504,346,361)}${link(437,325,563,325)}${link(654,289,871,151)}${link(667,325,858,325)}${link(654,361,871,504)}${ratio(240,221,32,'molar mass (g)')}${ratio(237,325,0,'22.4 dm³ at STP')}${ratio(235,429,-33,'6.022 × 10²³',true)}${ratio(760,221,-32,'molar mass (g)')}${ratio(763,325,0,'22.4 dm³ at STP')}${ratio(765,429,33,'6.022 × 10²³',true)}</svg>`;
}

