chem11WordVocabulary["vacuum distillation"]={"ur": "خلا میں کشید", "ps": "په خلا کې تقطیر"};
chem11WordVocabulary["glycerine"]={"ur": "گلیسرین", "ps": "ګلیسرین"};
chem11WordVocabulary["decompose"]={"ur": "تحلیل ہونا؛ کیمیائی طور پر ٹوٹنا", "ps": "تجزیه کېدل"};
